'use strict';
const PAPER='Functional Success versus Database-State, Behavioral, and Operational Contracts in AI-Generated PostgreSQL Schema Migrations';
const icons={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6ZM2 13l10 6 10-6M2 17l10 6 10-6"/>',grid:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12"/>',db:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v5h5M8 12h8m-8 4h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',warning:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v.1"/>',save:'<path d="M4 3h14l3 3v15H3V3h1Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/>',swap:'<path d="M4 8h15m-4-4 4 4-4 4M20 16H5m4-4-4 4 4 4"/>',play:'<path d="m7 4 14 8-14 8V4Z"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',refresh:'<path d="M20 7v6h-6M4 17v-6h6M20 12a8 8 0 0 0-14-5M4 12a8 8 0 0 0 14 5"/>'};
const icon=(name,cls='')=>`<svg class="svg ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages=['connect','capabilities','select','review','running','results','save'];
const stageNames=[['DB 연결','Connect DBs'],['사전 확인','Preflight'],['검사 선택','Choose checks'],['실행 전 확인','Review'],['검사 진행','Run checks'],['결과 확인','Results'],['결과 저장','Save results']];
const categoryDefs=[{key:'data',name:['데이터','Data'],desc:['전체 값·누락·중복·참조 관계','All values, missing rows, duplicates and relationships'],detail:['DATA-01 · 모든 선택 컬럼의 정확한 값과 중복 개수','DATA-02 · 입증 가능한 키·참조·제약 위반'],en:['DATA-01 · Exact values and duplicate multiplicities','DATA-02 · Evidence of key, reference or constraint violations']},{key:'schema',name:['구조·제약','Schema & constraints'],desc:['컬럼·자료형·키·제약·인덱스·partition','Columns, types, keys, constraints, indexes and partitions'],detail:['SCHEMA-01 · 컬럼 순서·타입·NULL·기본값·계산식','SCHEMA-02 · PK·UNIQUE·FK·CHECK·활성/검증 상태','SCHEMA-03 · 인덱스·partition 키와 경계'],en:['SCHEMA-01 · Column order, type, NULL, default and expressions','SCHEMA-02 · Keys, references, CHECKs and validation state','SCHEMA-03 · Indexes, partition keys and bounds']},{key:'access',name:['사용자·권한','Users & permissions'],desc:['사용자·역할·소유자·권한·행 정책','Users, roles, ownership, grants and row policies'],detail:['ACCESS-01 · 같은 이름 principal·멤버십·권한 정의','ACCESS-02 · RLS·DEFINER·실행 문맥 정의','2개 예시 항목은 조회 범위를 확인하지 못했습니다.'],en:['ACCESS-01 · Same-name principals, membership and grants','ACCESS-02 · RLS, DEFINER and execution context','Full visibility is unconfirmed for 2 sample checks.']},{key:'objects',name:['관련 객체','Related objects'],desc:['view·함수·trigger·sequence·사용자 타입','Views, routines, triggers, sequences and user types'],detail:['OBJECT-01 · 정의·signature·소유·참조 연결','OBJECT-02 · 번호 발급 없는 sequence·identity 상태','OBJECT-03 · 사용자 타입·enum·domain·외부 객체'],en:['OBJECT-01 · Definitions, signatures, owners and references','OBJECT-02 · Sequence and identity state without advancing values','OBJECT-03 · User types, enums, domains and external objects']},{key:'trial',name:['별도 DB 동작 시험','Behavior tests in a separate DB'],desc:['선택 기능 · 시험 DB에서만 입력·수정·삭제','Optional · Insert, update and delete only in a test DB'],detail:['BEHAVIOR-01 · 확인한 값과 기대 결과의 기본 동작','BEHAVIOR-02 · 선택 역할의 허용·거부·행 제한','앱 소유 자료만 정리하며 남은 변경을 따로 표시합니다.'],en:['BEHAVIOR-01 · Basic behavior using confirmed values and expectations','BEHAVIOR-02 · Allowed, denied and filtered actions of selected roles','Only app-owned data is cleaned up. Remaining changes are separate.']}];
const initial=()=>({screen:'home',visited:new Set(),dbms:'SQL Server',source:{host:'source.example.invalid',port:'1433',db:'migration_sample',user:'demo_reader'},target:{host:'target.example.invalid',port:'1433',db:'migration_sample',user:'demo_reader'},connected:false,busy:false,error:'',advanced:false,selected:new Set(['data','schema','access','objects']),tables:new Set(['demo.customers','demo.orders','demo.line_items']),maps:{'demo.customers':'demo.customers','demo.orders':'demo.orders','demo.line_items':'demo.line_items'},expanded:new Set(),trial:{host:'trial.example.invalid',db:'migration_test',validInput:'1',invalidInput:'-1',ready:false,consent:false},stopped:false,run:null,filter:'all',formats:new Set(['json']),saved:false});
let state=initial(),lang='ko',timer=null,modal=null,toastTimer=null,tableQuery='';
const t=(ko,en)=>lang==='ko'?ko:en;
const btn=(action,label,kind='',name='',disabled=false)=>`<button type="button" class="btn ${kind}" data-action="${action}" ${disabled?'disabled':''}>${name?icon(name):''}<span>${label}</span></button>`;
const pill=(text,kind='')=>`<span class="pill ${kind}"><span class="dot"></span>${text}</span>`;
const notice=(title,text,kind='')=>`<div class="notice ${kind}" role="${kind==='error'?'alert':'note'}">${icon(kind==='error'||kind==='warn'?'warning':'info')}<div><strong>${title}</strong><p>${text}</p></div></div>`;
const heading=(title,desc)=>`<div class="page-heading"><h1 id="screen-title" tabindex="-1">${title}</h1><p>${desc}</p></div>`;
const catName=key=>{const c=categoryDefs.find(c=>c.key===key);return c?t(...c.name):key};
const field=(label,key,value,extra='',type='text')=>`<div class="field"><label class="label" for="${key.replaceAll('.','-')}">${label}</label><input id="${key.replaceAll('.','-')}" data-field="${key}" type="${type}" value="${esc(value)}" autocomplete="off" spellcheck="false" ${extra}></div>`;
function topAndRail(){const stage=state.screen==='trial'?'select':state.screen;const index=stages.indexOf(stage);return `<header class="topbar"><div class="brand">${icon('shield')}<span>DB-Migration-Verifier</span></div><span class="preview">${t('설계 시안 · 실제 DB 연결 없음','Design preview · No real database connection')}</span><button type="button" class="language" data-action="language" aria-label="${t('영어로 변경','Switch to Korean')}">${lang==='ko'?'한국어 / EN':'English / KO'}</button></header><aside class="rail"><div class="rail-title">${t('마이그레이션 결과 비교','Migration result comparison')}</div><nav class="steps" aria-label="${t('검사 진행 단계','Verification steps')}">${stages.map((s,i)=>{const enabled=state.visited.has(s)&&state.screen!=='running';return `<button type="button" class="step ${index===i?'active':''} ${state.visited.has(s)&&i<index?'done':''}" data-action="stage:${s}" ${!enabled?'disabled':''} ${index===i?'aria-current="step"':''}><span class="step-index">${state.visited.has(s)&&i<index?icon('check'):i+1}</span><span>${t(...stageNames[i])}</span></button>`}).join('')}</nav><div class="rail-note"><strong>${t('비교는 읽기 전용','Read-only comparison')}</strong>${t('동작 시험의 쓰기는 별도 시험 DB에서만 합니다.','Behavior-test writes belong only in a separate test DB.')}</div></aside>`}
function home(){return `<div class="welcome">${heading(t('마이그레이션 결과를 비교하세요','Verify your migration results'),t('옮긴 뒤의 두 DB를 비교하고, 확인한 범위까지 분명하게.','Compare the two databases and see exactly what has been verified.'))}<div class="welcome-layout"><div><p class="help">${t('마이그레이션을 마친 개발자가 논문의 다축 검증 방법으로 두 DB의 데이터·구조·권한·객체를 비교하고, 차이와 확인하지 못한 영역을 찾도록 돕습니다.','Helps developers after migration compare data, schema, permissions and objects using the paper’s multi-axis approach, and identify differences and unverified areas.')}</p></div><aside class="sample-report" aria-label="${t('예시 검사 보고서','Sample verification report')}"><div class="report-head"><span>${t('예시 결과 미리보기','Sample result preview')}</span>${icon('file')}</div><div class="report-title">${t('차이와 확인 범위를<br>함께 봅니다.','Differences and verified<br>scope, together.')}</div><div class="report-line"><span>${t('불일치 항목','Different checks')}</span><b class="red">3</b></div><div class="report-line"><span>${t('확인 불가·미검증','Unverified checks')}</span><b class="amber">2</b></div><div class="report-line"><span>${t('일치 항목','Equal checks')}</span><b>45</b></div><p class="report-foot">${t('이 수치는 예시입니다.<br>실제 DB에 접속하지 않습니다.','These counts are samples.<br>No actual database connection.')}</p></aside></div><section class="home-entry" aria-label="${t('시작 방법','Getting started')}"><div class="home-actions"><div class="main-entry-actions">${btn('start',t('새 검사 시작','Start a new check'),'primary hero','arrow')}${btn('open',t('검사 결과 파일로 보기','View a result file'),'file-entry','file')}</div>${btn('sample',t('예시 결과 보기','See sample results'),'quiet sample-entry')}</div><p class="entry-hint">${icon('info')}<span>${t('저장한 결과 JSON은 DB 연결이나 새 검사 없이 바로 열어 확인할 수 있습니다.','Open a saved result JSON without connecting to a DB or running a new check.')}</span></p></section><div class="three-actions"><article><div class="action-number">01</div><h3>${t('두 DB를 연결합니다','Connect two databases')}</h3><p>${t('접속 후 앱이 조회 가능한 범위와 필요한 준비를 안내합니다.','The app checks visibility and explains any additional preparation.')}</p></article><article><div class="action-number">02</div><h3>${t('범위를 고르고 비교합니다','Choose what to compare')}</h3><p>${t('데이터·구조·권한·객체를 선택하고 테이블 대응을 확인합니다.','Select categories and confirm how tables are matched.')}</p></article><article><div class="action-number">03</div><h3>${t('차이와 미검증을 확인합니다','Review differences and gaps')}</h3><p>${t('확인한 결과를 구분해 보고, 안전한 결과 파일로 보관합니다.','Review verified outcomes and save a report without row values.')}</p></article></div><div class="paper">${icon('file')}<div><div class="small">${t('이 앱의 연구 근거','Research behind this app')}</div><h2>${PAPER}</h2><p>${t('기본 기능 성공과 넓은 DB 계약 충족을 구분하는 연구를 검사 분류와 미검증 표시에 반영합니다.','The research distinction between functional success and wider contracts informs the check categories and unverified states.')}</p></div>${btn('research',t('연구 반영 보기','Research mapping'),'quiet')}</div></div>`}
function connectionSide(side){const data=state[side];return `<section class="panel panel-pad"><div class="form-head"><div class="role-mark">${icon('db')}</div><div><h2>${side==='source'?t('원본 DB','Source DB'):t('대상 DB','Target DB')}</h2><small>${side==='source'?t('마이그레이션 전 상태','Before migration'):t('마이그레이션 후 상태','After migration')}</small></div>${pill(state.connected?t('예시 연결 확인','Sample connected'):t('미확인','Not checked'),state.connected?'ok':'')}</div><div class="field-row">${field(t('서버 주소','Server'),`${side}.host`,data.host)}${field(t('포트','Port'),`${side}.port`,data.port,'min="1" max="65535"','number')}</div>${field(t('데이터베이스','Database'),`${side}.db`,data.db)}${field(t('조회 계정','Reader account'),`${side}.user`,data.user)}<div class="field"><label class="label" for="${side}-pass">${t('비밀번호','Password')}</label><input id="${side}-pass" type="password" placeholder="${t('시안에서는 실제 비밀번호를 입력하지 않습니다','Do not enter a real password in this preview')}" disabled><small>${t('실제 앱에서는 기본 미저장, 선택 시 OS 보안 저장소를 사용합니다.','The actual app will not save credentials by default; OS vault storage is optional.')}</small></div></section>`}
function connect(){return `${heading(t('비교할 두 DB를 연결하세요','Connect the databases to compare'),t('같은 DBMS의 원본과 대상을 지정합니다. 접속 정보는 결과 파일에 넣지 않습니다.','Choose a source and target of the same DBMS. Connection details stay out of result files.'))}<fieldset class="dbms-fieldset"><legend>${t('비교할 데이터베이스 종류','Database engine to compare')}</legend><div class="dbms-grid">${[['SQL Server','Microsoft · 1433'],['PostgreSQL','PostgreSQL · 5432'],['MySQL','MySQL · 3306'],['MariaDB','MariaDB · 3306']].map(([name,desc],i)=>`<label class="dbms-option">${icon('db')}<span><strong>${name}</strong><small>${desc}</small></span><input id="dbms-${i}" type="radio" name="dbms" data-field="dbms" value="${name}" ${state.dbms===name?'checked':''} aria-label="${name}"></label>`).join('')}</div><p class="dbms-note">${t('원본과 대상은 같은 종류로 비교합니다. 선택하면 양쪽 예시 포트도 바뀝니다.','Source and target use the same engine. Selecting one updates both sample ports.')}</p></fieldset><div class="split">${connectionSide('source')}${connectionSide('target')}</div><div class="section">${btn('advanced',t('고급 연결 설정','Advanced connection settings'),'quiet','chevron').replace('data-action="advanced"',`data-action="advanced" aria-expanded="${state.advanced}" aria-controls="advanced-settings"`)}${state.advanced?`<div class="panel panel-pad enter" id="advanced-settings"><div class="split"><div><h3>${t('TLS · 인증서 검증','TLS · Certificate verification')}</h3><p class="muted">${t('기본은 인증서와 서버 이름 검증입니다. 실패 시 보안을 자동으로 낮추지 않습니다.','Certificates and server names are verified. Failures will not trigger a silent security downgrade.')}</p></div><div><h3>${t('인증 · 제한 시간','Authentication · Timeouts')}</h3><p class="muted">${t('실제 앱에서 지원되는 인증 방식과 연결·명령 제한 시간을 안내합니다. 이 시안은 DB 계정 입력 구조만 보여줍니다.','The actual app will expose supported authentication and connection/command limits. This preview shows only the form structure.')}</p></div></div></div>`:''}</div>${state.error?notice(t('연결 정보를 확인하세요','Check connection details'),esc(state.error),'error'):''}${state.connected?notice(t('양쪽 예시 연결을 확인했습니다','Both sample connections are checked'),t('이어서 어떤 범위를 읽을 수 있는지 확인합니다. 실제 서버에 접속한 결과는 아닙니다.','Next, check visibility. This is not evidence of a real server connection.'),'ok'):''}`}
function capabilities(){return `${heading(t('앱이 확인할 수 있는 범위입니다','What the app can verify'),t('권한 이름을 미리 알 필요는 없습니다. 가능한 검사와 확인하지 못한 부분을 먼저 보여드립니다.','You do not need to know permission names. The app first shows available checks and visibility gaps.'))}<div class="table-shell"><table class="capability-table"><thead><tr><th>${t('검사 분류','Category')}</th><th>${t('원본 / 대상','Source / target')}</th><th>${t('검사 가능 범위','Capability')}</th><th>${t('안내','Details')}</th></tr></thead><tbody>${categoryDefs.filter(c=>c.key!=='trial').map(c=>`<tr><td><strong>${t(...c.name)}</strong><small>${t(...c.desc)}</small></td><td class="capability-state">${pill(t('연결 확인','Connected'),'ok')}</td><td class="capability-state">${pill(c.key==='access'?t('일부 가능','Partially available'):t('가능','Available'),c.key==='access'?'warn':'ok')}</td><td><div class="capability-details"><span>${c.key==='access'?t('권한 정의 2개 조회 범위 미확인','Visibility unconfirmed for 2 grant checks'):t('선택 대상의 예시 조회 가능','Sample selected objects are readable')}</span>${c.key==='access'?btn('permissions',t('필요한 권한 보기','Required permissions'),'quiet'):''}</div></td></tr>`).join('')}</tbody></table></div>${notice(t('보이지 않는 객체를 “없음”으로 처리하지 않습니다','Hidden objects are not treated as absent'),t('읽지 못한 항목은 검사 후에도 확인 불가로 남습니다. 읽을 수 있는 부분의 차이는 계속 확인할 수 있습니다.','Unreadable items remain unverified. Differences in readable areas can still be checked.'),'warn')}<section class="section"><h2>${t('별도 DB 동작 시험은 선택입니다','Behavior tests are optional')}</h2><p class="muted">${t('기본 비교는 읽기 전용입니다. 입력·수정·삭제 시험은 다음 화면에서 별도 시험 DB를 준비한 경우에만 선택합니다.','The default comparison is read-only. Inserts, updates and deletes require a separate prepared test DB.')}</p></section>`}


function updateSelectionFooter(){const footerNode=document.querySelector('.footer');if(footerNode)footerNode.innerHTML=footer()}
function trialPreparation(){if(!state.selected.has('trial'))return '';const ready=state.trial.ready;return notice(ready?t('시험 DB 준비가 확인됐습니다 · 예시','Test DB preparation confirmed · Sample'):t('동작 시험에 사용할 공간을 준비하세요','Prepare a space for behavior tests'),ready?t('확인한 예시 DB에서만 동작 시험을 진행합니다. 원본·대상 비교는 읽기 전용입니다.','Behavior tests use only the confirmed sample test DB. Source and target comparison stays read-only.'):t('원본·대상과 분리된 시험 DB와 값·기대 결과를 확인해야 합니다.','Confirm a separate test DB, trial inputs and expected outcomes.'),ready?'ok':'warn')+`<div class="trial-prepared-row">${btn('trial',ready?t('시험 준비 수정','Edit test setup'):t('시험 DB 준비','Prepare a test DB'),'','db')}${ready?`<div class="prepared-db" role="status">${icon('db')}<div><strong>${esc(state.trial.db)}</strong><span>${esc(state.dbms)} · ${esc(state.trial.host)}</span><small>${t('준비 확인 완료 · 예시 정보','Preparation confirmed · Sample details')}</small></div>${icon('check')}</div>`:''}</div>`}
function updateScopeSelection(){document.querySelector('.scope-heading span:last-child').textContent=`${state.selected.size} / 5 ${t('선택','selected')}`;document.getElementById('trial-preparation').innerHTML=trialPreparation();updateSelectionFooter();document.getElementById('announcer').textContent=`${state.selected.size} ${t('개 분류 선택','categories selected')}`}
function filteredTables(){const query=tableQuery.trim().toLowerCase();return Object.keys(state.maps).filter(name=>!query||name.toLowerCase().includes(query)||state.maps[name].toLowerCase().includes(query))}
function tableCountLabel(){return `${filteredTables().length} ${t('개 표시 · 전체','shown · of')} ${Object.keys(state.maps).length} ${t('개','tables')}`}
function tableRows(){return filteredTables().map(name=>`<tr><td><label class="table-choice"><input type="checkbox" data-table="${name}" ${state.tables.has(name)?'checked':''}><span class="mono">${name}</span></label></td><td class="mono">${esc(state.maps[name])}</td><td><span class="match-method ${state.maps[name]===name?'':'manual'}">${icon(state.maps[name]===name?'check':'swap')}${state.maps[name]===name?t('동일 이름','Same name'):t('수동 · 이름 차이 유지','Manual · Name difference retained')}</span></td><td>${btn('mapping:'+name,t('대응 변경','Change match'),'quiet','swap')}</td></tr>`).join('')||`<tr><td colspan="4" class="table-empty">${t('검색된 테이블이 없습니다. 검색어를 바꿔 보세요.','No tables match. Try a different search.')}</td></tr>`}
function syncTableSelection(){document.querySelectorAll('[data-table]').forEach(input=>input.checked=state.tables.has(input.dataset.table));const shown=filteredTables(),count=shown.filter(name=>state.tables.has(name)).length;const checkbox=document.getElementById('table-all');if(checkbox){checkbox.checked=shown.length>0&&count===shown.length;checkbox.indeterminate=count>0&&count<shown.length;checkbox.disabled=!shown.length}const clear=document.querySelector('[data-action="clear-tables"]');if(clear)clear.disabled=!count;const clearSearch=document.querySelector('[data-action="clear-search"]');if(clearSearch)clearSearch.disabled=!tableQuery;const label=document.getElementById('table-selection-count');if(label)label.textContent=`${state.tables.size} / ${Object.keys(state.maps).length} ${t('개 선택','selected')}`}
function updateTableResults(){const body=document.getElementById('table-results');if(!body)return;body.innerHTML=tableRows();document.getElementById('table-search-count').textContent=tableCountLabel();syncTableSelection()}
function matchingOptions(query=''){const current=modal.payload;return [...Object.keys(state.maps),'archive.orders'].filter(name=>name.toLowerCase().includes(query.trim().toLowerCase())).map((name,i)=>{const busy=Object.entries(state.maps).some(([source,target])=>source!==current&&target===name);return `<label class="match-option ${busy?'unavailable':''}"><input id="match-option-${i}" type="radio" name="match-target" data-modal-field="draft" value="${name}" ${modal.draft===name?'checked':''} ${busy?'disabled':''} aria-describedby="match-note-${i}"><span><span class="mono">${esc(name)}</span><small id="match-note-${i}">${busy?t('다른 원본 테이블과 이미 대응되어 있습니다.','Already matched to another source table.'):name===current?t('원본과 이름이 같습니다.','Same name as the source.'):t('이름 차이는 결과에 남습니다.','Name differences remain in the result.')}</small></span><b class="match-badge" data-target-name="${name}">${busy?t('사용 중','In use'):modal.draft===name?t('선택','Selected'):''}</b></label>`}).join('')||`<p class="table-empty">${t('검색된 대상이 없습니다. 검색어를 바꿔 보세요.','No matching targets. Try another search.')}</p>`}
function select(){return `${heading(t('무엇을 검사할지 선택하세요','Choose what to verify'),t('읽을 수 있는 비교 분류는 기본 선택합니다. 분류 안의 세부 항목도 검사 대상으로 유지합니다.','Readable comparison categories are selected by default, including their detailed checks.'))}<div class="scope-heading"><span>${t('검사 분류','Check categories')}</span><span>${state.selected.size} / 5 ${t('선택','selected')}</span></div><div>${categoryDefs.map(c=>`<section class="category"><div class="category-head"><button type="button" class="category-toggle" data-action="expand:${c.key}" aria-expanded="${state.expanded.has(c.key)}" aria-controls="category-detail-${c.key}"><span class="category-icon" aria-hidden="true">${icon({data:'db',schema:'grid',access:'shield',objects:'layers',trial:'play'}[c.key])}</span><span class="category-text"><strong>${t(...c.name)}</strong><small>${t(...c.desc)}</small></span>${pill(c.key==='trial'?(state.trial.ready?t('예시 준비됨','Sample ready'):t('별도 DB 준비 필요','Test DB required')):c.key==='access'?t('일부 가능','Partial'):t('가능','Available'),c.key==='trial'?(state.trial.ready?'ok':'warn'):c.key==='access'?'warn':'ok')}${icon('chevron','chevron')}</button><label class="category-choice"><input type="checkbox" data-category="${c.key}" aria-label="${t(...c.name)} ${t('검사 선택','check selection')}" ${state.selected.has(c.key)?'checked':''}></label></div><div id="category-detail-${c.key}" class="category-body-wrap ${state.expanded.has(c.key)?'is-open':''}" aria-hidden="${!state.expanded.has(c.key)}" ${state.expanded.has(c.key)?'':'inert'}><div class="category-body"><ul>${(lang==='ko'?c.detail:c.en).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section>`).join('')}</div><div id="trial-preparation">${trialPreparation()}</div><section class="section"><div class="section-heading"><h2>${t('검사할 테이블과 대응','Tables and matching')}</h2><span class="small" id="table-selection-count">${state.tables.size} / ${Object.keys(state.maps).length} ${t('개 선택','selected')}</span></div><div class="table-toolbar"><div class="search-field">${icon('search')}<label class="sr" for="table-search">${t('테이블 검색','Search tables')}</label><input id="table-search" type="search" placeholder="${t('테이블 이름으로 검색','Search by table name')}" value="${esc(tableQuery)}" autocomplete="off"><button class="btn quiet icon-button" type="button" data-action="clear-search" aria-label="${t('테이블 검색 지우기','Clear table search')}">${icon('close')}</button></div><label class="bulk-choice"><input id="table-all" type="checkbox" data-bulk="tables"><span>${t('검색 결과 전체 선택','Select all matching tables')}</span></label>${btn('clear-tables',t('선택 해제','Deselect matches'),'quiet')}</div><div class="table-meta"><span id="table-search-count">${tableCountLabel()}</span><span>${t('검색은 선택 범위를 바꾸지 않습니다.','Search does not change your selection.')}</span></div><div class="table-shell"><table><thead><tr><th>${t('원본 테이블','Source table')}</th><th>${t('대상 테이블','Target table')}</th><th>${t('대응 방식','Matching')}</th><th></th></tr></thead><tbody id="table-results">${tableRows()}</tbody></table></div><p class="small" style="margin-top:12px">${t('사용자·역할·소유자는 같은 이름으로 비교합니다. 수동 대응 후에도 이름·값·정의 차이를 보고합니다.','Users, roles and owners are compared by the same name. Manual matching still reports name, value and definition differences.')}</p></section>${state.error?notice(t('선택을 확인하세요','Check your selection'),esc(state.error),'error'):''}`}
function trial(){return `${heading(t('동작 시험은 별도 DB에서 합니다','Behavior tests use a separate database'),t('앱이 원본·대상을 복제하거나 초기화하지 않습니다. 변경 가능한 시험 DB를 사용자가 준비합니다.','Prepare your own mutable test DB. The app does not clone or reset the source or target.'))}<div class="split"><section class="panel panel-pad"><h2>${t('시험 DB 연결','Test DB connection')}</h2>${field(t('서버 주소','Server'),'trial.host',state.trial.host)}${field(t('시험 데이터베이스','Test database'),'trial.db',state.trial.db)}<div class="notice"><div><strong>${t('분리 확인','Isolation check')}</strong><p>${t('실제 앱은 연결 경로와 DB 식별을 확인합니다. 이 시안은 같은 예시 DB를 지정하는 오류만 재현합니다.','The actual app must verify routing and DB identity. This preview only demonstrates rejecting the same sample DB.')}</p></div></div></section><section class="panel panel-pad"><h2>${t('DBMS별 준비 안내','DBMS preparation guidance')}</h2><ol class="muted" style="padding-left:20px"><li>${t('변경 가능한 별도 시험 DB를 준비합니다.','Prepare a separate database that may be modified.')}</li><li>${t('대상 구조·필요 계정·권한을 갖춥니다.','Provide target schema and required test accounts/permissions.')}</li><li>${t('동작별 시험 값과 기대 결과를 확인합니다.','Confirm test inputs and expected outcomes.')}</li></ol><p class="small">${t('백엔드 업무 환경은 이 기본 시험의 필수 준비물이 아닙니다.','A backend business environment is not required for these basic tests.')}</p></section></div><section class="section"><h2>${t('기본 시험안 · 예시','Generated trial plan · Example')}</h2><div class="table-shell" style="margin-top:12px"><table><thead><tr><th>${t('순서','Order')}</th><th>${t('시험','Action')}</th><th>${t('확인할 결과','Expected observation')}</th></tr></thead><tbody><tr><td>1</td><td>${t('앱 생성 자료 입력·조회','Insert and read app-owned test data')}</td><td>${t('정상 입력 허용·자동값 확인','Valid input accepted; automatic values checked')}</td></tr><tr><td>2</td><td>${t('앱 생성 자료 수정·조회','Update and read app-owned data')}</td><td>${t('제약 충족·위반 입력의 결과 구분','Valid and invalid input outcomes distinguished')}</td></tr><tr><td>3</td><td>${t('앱 생성 자료 삭제·정리 확인','Delete app-owned data and check cleanup')}</td><td>${t('기존 자료 불변·남은 변경 별도 표시','Existing data untouched; remaining changes reported')}</td></tr></tbody></table></div><div class="panel panel-pad" style="margin-top:16px"><p class="small">${t('합성 시험 제약: amount ≥ 0 · 아래 값은 예시이며 실제 데이터가 아닙니다.','Synthetic trial constraint: amount ≥ 0 · These are example values, not real data.')}</p><div class="split">${field(t('정상 입력 시험값 · 기대: 허용','Valid input · Expected: accepted'),'trial.validInput',state.trial.validInput)}${field(t('제약 위반 시험값 · 기대: 거부','Constraint-violating input · Expected: rejected'),'trial.invalidInput',state.trial.invalidInput)}</div></div><label class="choice" style="margin-top:16px"><input type="checkbox" data-flag="trial.consent" ${state.trial.consent?'checked':''}><span>${t('예시 시험안과 기대 결과를 확인했습니다.','I have reviewed the sample trial plan and expected results.')}</span></label></section>${state.error?notice(t('시험 준비를 확인하세요','Check test preparation'),esc(state.error),'error'):''}${state.trial.ready?notice(t('예시 시험 준비가 확인됐습니다','Sample trial setup is confirmed'),t('실제 쓰기나 DB 분리 검증을 수행한 것은 아닙니다.','No actual writes or database-isolation checks have been performed.'),'ok'):''}`}
function review(){return `${heading(t('시작 전에 범위를 확인하세요','Review the scope before starting'),t('이번 검사가 읽는 대상과 확인하지 못할 부분을 한 번에 확인합니다.','Review the databases, selected checks and known limitations together.'))}<div class="panel panel-pad summary-list"><div class="summary-item"><span>DBMS</span><strong>${esc(state.dbms)} · ${t('예시 연결','Sample connections')}</strong></div><div class="summary-item"><span>${t('원본 → 대상','Source → target')}</span><div class="mono">${esc(state.source.db)} → ${esc(state.target.db)}<small>${t('원본과 대상은 서로 다른 예시 서버입니다.','Source and target are separate sample servers.')}</small></div></div><div class="summary-item"><span>${t('선택 분류','Selected categories')}</span><div>${[...state.selected].map(catName).join(' · ')}</div></div><div class="summary-item"><span>${t('검사 테이블','Selected tables')}</span><div>${state.tables.size} ${t('개 · 대응 확인','tables · Matching reviewed')}</div></div><div class="summary-item"><span>${t('선택하지 않은 분류','Excluded categories')}</span><div>${categoryDefs.filter(c=>!state.selected.has(c.key)).map(c=>t(...c.name)).join(' · ')||t('없음','None')}</div></div><div class="summary-item"><span>${t('변경 경계','Write boundary')}</span><div>${t('원본·대상 읽기 전용','Source and target: read-only')}${state.selected.has('trial')?`<br>${t('동작 시험: 준비한 시험 DB에서만 쓰기','Behavior tests: writes only in the prepared test DB')}`:''}</div></div></div>${state.selected.has('access')?notice(t('권한 조회 2개 항목은 확인 불가로 남습니다','Two permission checks will remain unverified'),t('그 밖의 가능한 검사는 진행하지만 전체 일치로 표시하지 않습니다.','Other available checks can proceed, but the result cannot be presented as fully equal.'),'warn'):''}<label class="choice" style="margin-top:20px"><input type="checkbox" data-flag="stopped" ${state.stopped?'checked':''}><span>${t('원본과 대상의 쓰기를 멈춘 상태임을 확인했습니다.','I confirm that writes to source and target are stopped.')}</span></label><p class="small">${t('시안에서의 확인입니다. 앱이 모든 동시 쓰기를 탐지한다는 보장은 아닙니다.','This is a preview confirmation, not a guarantee that all concurrent writes can be detected.')}</p>`}
const totalFor=key=>key==='data'?state.tables.size*4:key==='schema'?state.tables.size*6:key==='access'?8:key==='objects'?12:4;
function makeRun(sample=false){const groups=categoryDefs.filter(c=>state.selected.has(c.key)).map(c=>({key:c.key,total:totalFor(c.key),done:0,status:'pending',equal:0,different:0,unknown:0}));return {id:`UI-${Date.now().toString(36).toUpperCase()}`,interrupted:false,complete:false,groups,trialSelected:state.selected.has('trial'),startedAt:new Date().toISOString(),sample,tableNames:[...state.tables],maps:{...state.maps}}}
function completeGroup(g){g.status='completed';g.done=g.total;g.different=g.key==='data'&&state.tables.has('demo.orders')?1:g.key==='schema'?(state.tables.has('demo.orders')?1:0)+[...state.tables].filter(name=>state.maps[name]!==name).length:g.key==='access'?1:g.key==='trial'?1:0;g.unknown=g.key==='access'?2:0;g.equal=g.total-g.different-g.unknown}
function runSummary(){const groups=state.run?.groups||[];return {total:groups.reduce((a,g)=>a+g.total,0),done:groups.reduce((a,g)=>a+g.done,0),equal:groups.filter(g=>g.key!=='trial').reduce((a,g)=>a+g.equal,0),different:groups.filter(g=>g.key!=='trial').reduce((a,g)=>a+g.different,0),unknown:groups.reduce((a,g)=>a+g.total-g.equal-g.different,0)}}
function groupState(g){return g.status==='completed'?pill(t('완료','Completed'),'ok'):g.status==='running'?pill(t('진행 중','Running'),'accent'):g.status==='interrupted'?pill(t('중단','Interrupted'),'warn'):pill(t('미시작','Not started'))}
function running(){const s=runSummary();const current=state.run.groups.find(g=>g.status==='running');return `${heading(state.run.interrupted?t('검사가 중단됐습니다','The check was interrupted'):state.run.complete?t('예시 검사가 끝났습니다','Sample checks are finished'):t('선택한 범위를 비교하고 있습니다','Comparing the selected scope'),t('현재 화면의 진행과 결과는 예시입니다. DB 쿼리를 실행하지 않습니다.','Progress and outcomes here are samples. No database queries are being executed.'))}<section class="panel panel-pad"><div class="progress-main"><div><div class="progress-number num" id="processed-count">${s.done}<small> / ${s.total} ${t('항목','checks')}</small></div><p id="progress-note">${current?`<span class="running-dot"></span>${catName(current.key)} · ${t('예시 대조 중','Sample comparison')}`:state.run.interrupted?t('완료·중단·미시작 범위를 나눠 보관합니다.','Completed, interrupted and pending scopes remain separate.'):t('불일치와 확인 불가 영역을 결과에서 확인하세요.','Review differences and unverified areas in the results.')}</p></div><span class="mono">${state.run.id}</span></div><div class="meter" aria-label="${t('예시 처리 항목','Sample processed checks')}" role="progressbar" aria-valuemin="0" aria-valuemax="${s.total}" aria-valuenow="${s.done}"><div class="meter-bar" style="transform:scaleX(${s.total?s.done/s.total:0})"></div></div></section><div class="table-shell section"><table><thead><tr><th>${t('검사 분류','Category')}</th><th>${t('실행 상태','Execution')}</th><th>${t('처리 항목','Processed')}</th></tr></thead><tbody>${state.run.groups.map(g=>`<tr><td><strong>${catName(g.key)}</strong></td><td data-run-state="${g.key}">${groupState(g)}</td><td class="mono" data-run-count="${g.key}">${g.done} / ${g.total}</td></tr>`).join('')}</tbody></table></div>${state.run.interrupted?notice(t('전체 재검사만 가능합니다','Only a full new check is available'),t('부분 결과를 확인할 수 있습니다. 중단 자료로 이어서 검사하거나 새 결과와 합치지 않습니다.','You can review the partial result. Interrupted data is not resumed or merged into a new run.'),'warn'):''}`}
function findings(){const rows=[];for(const g of state.run?.groups||[]){if(g.different&&g.key!=='trial'&&(g.key!=='schema'||(state.run.tableNames||[]).includes('demo.orders'))){rows.push(g.key==='data'?{id:'F-001',key:g.key,kind:'different',title:t('값 불일치','Value mismatch'),table:'demo.orders',column:'amount',reason:t('대응 행의 관측 값이 다릅니다. 실제 값과 행 키는 표시하지 않습니다.','An observed value differs in a matched row. Values and row keys are not displayed.')}:g.key==='schema'?{id:'F-002',key:g.key,kind:'different',title:t('NULL 허용 정의 불일치','NULL definition mismatch'),table:'demo.orders',column:'reference',reason:t('컬럼의 NULL 허용 속성이 다릅니다. 값 일치와 별도 검사입니다.','The column nullability differs. This is separate from value equality.')}: {id:'F-003',key:g.key,kind:'different',title:t('권한 정의 불일치','Grant definition mismatch'),table:'—',column:'—',reason:t('내부 객체 PR-003의 권한 정의가 다릅니다. 실제 계정명은 표시하지 않습니다.','Grant definitions differ for internal object PR-003. Actual principal names are not displayed.')})}if(g.key==='schema'&&g.status==='completed'){for(const [i,name] of (state.run.tableNames||[]).entries()){if(state.run.maps?.[name]&&state.run.maps[name]!==name)rows.push({id:'F-MAP-'+(i+1),key:'schema',kind:'different',title:t('테이블 이름 불일치','Table name mismatch'),table:name,column:'—',reason:t('수동 대응한 대상의 이름이 다릅니다. 값 비교와 별도로 이름 차이를 유지합니다.','The manually matched target has a different name. This difference is retained separately from value comparison.')})}}if(g.unknown){rows.push({id:'U-001',key:g.key,kind:'unknown',title:t('권한 정의 2개 조회 범위 미확인','Visibility unconfirmed for 2 grant checks'),table:'—',column:'—',reason:t('목록 가시성을 입증하지 못해 존재/누락을 판정하지 않았습니다.','Catalog completeness was not established; presence or absence was not adjudicated.')})}if(g.status!=='completed'){rows.push({id:'U-'+g.key,key:g.key,kind:'unknown',title:g.status==='interrupted'?t('검사 중단','Check interrupted'):t('미시작 검사','Check not started'),table:'—',column:'—',reason:`${g.total-g.done} ${t('항목을 끝까지 확인하지 못했습니다.','checks have not been completed.')}`})}}
return rows}
function categoryVerdict(g){if(g.status!=='completed')return pill(g.status==='interrupted'?t('중단 · 미검증','Interrupted · Unverified'):t('미검증','Unverified'),'warn');if(g.key==='trial')return pill(g.different?t('기대 불충족','Expectation unmet'):t('기대 충족','Expectations met'),g.different?'bad':'ok');return (g.different?pill(t('불일치','Different'),'bad'):'')+(g.unknown?' '+pill(t('확인 불가','Unverified'),'warn'):'')+(!g.different&&!g.unknown?pill(t('일치','Equal'),'ok'):'')}
function resultChart(){const groups=state.run.groups.filter(g=>g.key!=='trial');if(!groups.length)return '';const maximum=Math.max(5,Math.ceil(Math.max(...groups.map(g=>Math.max(g.equal,g.different,g.total-g.equal-g.different)))/5)*5);const names=[t('불일치','Different'),t('미검증','Unverified'),t('일치','Equal')];return `<figure class="result-chart"><div class="chart-heading"><div><h2>${t('비교 결과, 분류별로','Comparison results by category')}</h2><p>${t('분류를 눌러 세부 검사와 판정 근거를 확인하세요.','Select a category for detailed checks and evidence.')}</p></div><span class="chart-unit">${t('검사 항목 수','Check counts')}<br>${t('막대 공통 축','Shared bar scale')} 0–${maximum}</span></div><div class="result-columns" aria-hidden="true"><span>${t('검사 분류','Check category')}</span>${names.map((x,i)=>`<span class="${['red','amber','green'][i]}">${icon(['warning','info','check'][i])}${x}</span>`).join('')}<span></span></div><div class="result-rows">${groups.map(g=>{const unknown=g.total-g.equal-g.different;const counts=[g.different,unknown,g.equal];return `<button type="button" class="result-row" data-action="detail:${g.key}" aria-label="${catName(g.key)}: ${names.map((n,i)=>n+' '+counts[i]).join(', ')}. ${t('세부 보기','View details')}"><span class="result-category"><span class="category-icon">${icon({data:'db',schema:'grid',access:'shield',objects:'layers'}[g.key])}</span><span><strong>${catName(g.key)}</strong><small>${g.status==='completed'?t('실행 완료','Completed'):g.status==='interrupted'?t('중단 · 미검증 포함','Interrupted · Gaps retained'):t('미시작 · 미검증','Not started · Unverified')} · ${t('전체','Total')} ${g.total}</small></span></span>${counts.map((n,i)=>`<span class="result-count ${['different','unknown','equal'][i]} ${n===0?'zero':''}" data-count="${n}" data-kind="${['different','unknown','equal'][i]}"><b class="num">${n}</b><span class="mini-track" aria-hidden="true"><span class="mini-bar" style="width:${n/maximum*100}%"></span></span></span>`).join('')}<span class="row-chevron">${icon('chevron')}<span class="sr">${t('세부 보기','Details')}</span></span></button>`}).join('')}</div><figcaption class="chart-caption">${t('검사 항목 수를 비교합니다. 행 수나 전체 DB 성공률이 아닙니다. 미검증에는 확인 불가·중단·미시작 항목이 포함됩니다.','These are check counts, not row counts or a whole-DB success rate. Unverified includes unreadable, interrupted and unstarted checks.')}</figcaption></figure>`}
function trialResult(){const g=state.run.groups.find(g=>g.key==='trial');if(!g)return '';return `<section class="trial-result"><h2>${t('별도 DB 동작 시험','Behavior test · Separate DB')}</h2><button type="button" class="trial-result-row" data-action="detail:trial"><span><strong>${t('시험 기대 결과','Trial expectations')}</strong><small>${t('비교 결과와 별도 판정 · 정리 내역 포함','Separate from comparison · Includes cleanup details')}</small></span><span>${categoryVerdict(g)}</span><span class="mono">${t('충족 / 불충족 / 미검증','Met / unmet / unverified')}<br>${g.equal} / ${g.different} / ${g.total-g.equal-g.different}</span>${icon('chevron')}</button></section>`}
function results(){const s=runSummary();const hasTrialFailure=state.run.groups.some(g=>g.key==='trial'&&g.different);const title=state.run.interrupted?t('중단된 범위가 있습니다','Some checks were interrupted'):s.different?t('불일치가 발견됐습니다','Differences were found'):s.unknown?t('확인하지 못한 영역이 있습니다','Some areas remain unverified'):hasTrialFailure?t('동작 시험 기대를 충족하지 못했습니다','A behavior test did not meet expectations'):t('선택 범위 내 일치입니다','Equal within the selected scope');return `${heading(title,t('값·정의의 차이와 확인하지 못한 부분을 함께 봅니다. 선택하지 않은 범위는 검증한 것으로 표시하지 않습니다.','Review differences alongside unverified areas. Excluded scope is not presented as verified.'))}<div class="metrics"><div><div class="metric-label">${t('불일치 항목','Different checks')}</div><div class="metric-number red num">${s.different}</div></div><div><div class="metric-label">${t('확인 불가·미검증 항목','Unverified / unobserved')}</div><div class="metric-number amber num">${s.unknown}</div></div><div><div class="metric-label">${t('일치 항목','Equal checks')}</div><div class="metric-number green num">${s.equal}</div></div><div style="margin-left:auto"><div class="metric-label">${t('예시 검사 ID','Sample run ID')}</div><div class="mono">${state.run.id}</div></div></div>${resultChart()}${trialResult()}<section class="section"><div class="section-heading"><h2>${t('확인할 차이와 미검증 이유','Differences and reasons for gaps')}</h2>${btn('research',t('연구 연결','Research mapping'),'quiet','file')}</div><div class="filter-row" aria-label="${t('결과 필터','Result filter')}">${[['all',t('전체','All')],['different',t('불일치','Differences')],['unknown',t('확인 불가·미검증','Unverified')]].map(([key,label])=>btn('filter:'+key,label,state.filter===key?'selected':'')).join('')}</div><div id="findings" class="finding-list">${findings().filter(f=>state.filter==='all'||state.filter===f.kind).map(f=>`<article class="finding"><div class="finding-top"><strong>${f.title}</strong><span class="mono">${f.id}</span></div><p><span class="mono">${f.table} · ${f.column}</span></p><p>${f.reason}</p></article>`).join('')||`<div class="panel empty">${t('이 필터에 해당하는 항목이 없습니다.','No items match this filter.')}</div>`}</div></section>${state.run.trialSelected?notice(t('시험 판정과 정리는 별도입니다','Behavior outcomes and cleanup are separate'),state.run.groups.find(g=>g.key==='trial')?.status==='completed'?t('예시: 기대 3개 충족·1개 불충족. 앱 생성 자료 정리 실패 1건, 추적 가능한 잔여 T-001과 확인 불가 기록을 별도로 보고합니다. 실제 DB 변경은 없습니다.','Sample: 3 expectations met, 1 unmet. One cleanup failure, a traceable remaining artifact T-001, and unconfirmed effects are reported separately. No real DB was changed.'):t('시험은 완료하지 못했습니다. 정리 완료나 원상복구를 주장하지 않습니다.','The trial was not completed. Cleanup or restoration is not claimed.'),'warn'):''}<p class="small" style="margin-top:20px">${t('원본 결함: 이 예시에는 입증된 원본 결함이 없습니다. 실제 검사는 위반 근거가 있을 때만 별도로 표시합니다.','Source defects: none are substantiated in this sample. The actual app must require evidence of a violation.')}<br>${t('선택하지 않은 분류','Excluded categories')}: ${categoryDefs.filter(c=>!state.run.groups.some(g=>g.key===c.key)).map(c=>t(...c.name)).join(' · ')||t('없음','None')}</p>`}
function save(){return `${heading(t('확인한 범위를 결과 파일로 남기세요','Save the scope you have verified'),t('실제 값·행 키·계정명·접속 정보는 결과에 넣지 않습니다. 예시 결과 파일은 이 시안에서 다시 열 수 있습니다.','No row values, keys, principal names or connection details are included. Sample JSON files can be reopened in this preview.'))}<div class="download-options">${[['json',t('다시 열기용 JSON','JSON for reopening'),t('검사 범위·상태·안전한 결과','Scope, states and safe findings')],['csv','CSV',t('분류별 판정과 안전한 차이 목록','Category outcomes and safe findings')],['html','HTML',t('브라우저에서 읽는 예시 보고서','Readable sample report')]].map(([key,title,desc])=>`<label class="download-option"><input type="checkbox" data-format="${key}" ${state.formats.has(key)?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div><section class="section"><div class="panel panel-pad summary-list"><div class="summary-item"><span>${t('포함','Included')}</span><div>${t('예시 run ID, 선택 범위, 완료·중단·미시작, 판정과 확인 불가 이유, 안전한 finding 위치','Sample run ID, scope, completed/interrupted/pending states, outcomes, gap reasons and safe finding locations')}</div></div><div class="summary-item"><span>${t('제외','Excluded')}</span><div>${t('실제 값·PK·비밀번호·토큰·원 SQL 정의·접속 설정','Values, PKs, passwords, tokens, raw SQL definitions and connection settings')}</div></div></div></section>${state.saved?notice(t('예시 파일 다운로드를 요청했습니다','Sample file downloads were requested'),t('브라우저의 다운로드 결과를 확인하세요. 디스크 저장 성공을 이 화면만으로 확정하지 않습니다.','Check your browser downloads. This screen alone does not establish a successful disk save.'),'ok'):''}<div class="actions">${btn('open',t('저장한 결과 다시 열기','Reopen a saved result'),'','file')}${btn('restart',t('전체 재검사','Start a full new check'),'quiet','refresh')}</div>`}
function footer(){switch(state.screen){case'home':return `<span class="footer-hint">${t('로그인 없이 예시 흐름을 살펴볼 수 있습니다.','Explore the sample flow without logging in.')}</span>`;case'connect':return `${btn('back',t('뒤로','Back'),'quiet','back')}<span class="footer-hint">${t('연결 정보를 바꾸면 다시 확인합니다.','Changes require another connection check.')}</span><div class="footer-actions">${state.connected?btn('preflight',t('조회 범위 확인','Check visibility'),'primary','arrow',state.busy):`<button type="button" class="btn primary" data-action="connect" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':icon('db')}<span>${state.busy?t('확인 중…','Checking…'):t('두 연결 확인','Check both connections')}</span></button>`}</div>`;case'capabilities':return `${btn('back',t('뒤로','Back'),'quiet','back')}<span class="footer-hint">${t('미조회 영역은 결과에도 남습니다.','Visibility gaps stay in the result.')}</span><div class="footer-actions">${btn('choose',t('검사 범위 선택','Choose checks'),'primary','arrow')}</div>`;case'select':return `${btn('back',t('뒤로','Back'),'quiet','back')}<span class="footer-hint">${!state.selected.size?t('검사 분류를 하나 이상 선택하세요.','Select at least one check category.'):((state.selected.has('data')||state.selected.has('schema'))&&!state.tables.size)?t('검사할 테이블을 하나 이상 선택하세요.','Select at least one table to compare.'):state.selected.has('trial')&&!state.trial.ready?t('동작 시험을 준비하거나 선택을 해제하세요.','Prepare or deselect the behavior test.'):t('선택 범위와 제외 범위를 다음 화면에서 확인합니다.','Review selected and excluded scope next.')}</span><div class="footer-actions">${btn('review',t('실행 전 확인','Review before running'),'primary','arrow',!state.selected.size||((state.selected.has('data')||state.selected.has('schema'))&&!state.tables.size)||state.selected.has('trial')&&!state.trial.ready)}</div>`;case'trial':return `${btn('trial-back',t('검사 선택으로','Back to selection'),'quiet','back')}<span class="footer-hint">${t('실제 앱은 분리 확인과 시험안 확인이 필요합니다.','The actual app must verify isolation and the trial plan.')}</span><div class="footer-actions">${state.trial.ready?btn('trial-back',t('준비 확인 · 돌아가기','Ready · Return'),'primary','check'):btn('trial-check',t('시험 준비 확인','Confirm test setup'),'primary','check',!state.trial.consent)}</div>`;case'review':return `${btn('back',t('선택 수정','Edit selection'),'quiet','back')}<span class="footer-hint">${state.stopped?t('준비한 범위로 예시 검사를 시작합니다.','Start sample checks for the prepared scope.'):t('쓰기를 멈춘 상태를 확인하세요.','Confirm that writes are stopped.')}</span><div class="footer-actions">${btn('run',t('비교 시작','Start comparison'),'primary','play',!state.stopped)}</div>`;case'running':return `<span class="footer-hint">${state.run.interrupted?t('중단 이유: 사용자 취소 · 새 전체 검사만 가능','Reason: user cancellation · Full new check only'):t('화면 시안의 예시 검사입니다. 실제 DB 읽기·쓰기는 없습니다.','Simulated preview checks; no real DB reads or writes.')}</span><div class="footer-actions">${!state.run.complete&&!state.run.interrupted?btn('cancel',t('검사 취소','Cancel checks'),'danger','stop'):btn('show-results',t('결과 보기','View results'),'primary','arrow')}</div>`;case'results':return `${btn('restart',t('전체 재검사','Full new check'),'quiet','refresh')}<span class="footer-hint">${t('확인한 범위와 확인 불가 이유를 함께 보관합니다.','Save verified scope and reasons for gaps together.')}</span><div class="footer-actions">${btn('save',t('결과 저장','Save results'),'primary','save')}</div>`;case'save':return `${btn('back',t('결과로 돌아가기','Back to results'),'quiet','back')}<span class="footer-hint">${state.formats.size?t('브라우저 다운로드로 예시 파일을 만듭니다.','Create sample files via browser downloads.'):t('저장할 형식을 선택하세요.','Choose a file format.')}</span><div class="footer-actions">${btn('download',t('선택 형식 저장','Save selected formats'),'primary','save',!state.formats.size)}</div>`}}
function animateResult(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('.metric-number,.result-count b').forEach(x=>x.animate([{transform:'translateY(5px)',opacity:.6},{transform:'none',opacity:1}],{duration:220,easing:'cubic-bezier(.22,1,.36,1)'}));document.querySelectorAll('.mini-bar').forEach(x=>x.animate([{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration:320,easing:'cubic-bezier(.22,1,.36,1)'}))}
function render(focus=false){const scrollTop=document.getElementById('main')?.scrollTop||0;const before=document.activeElement;const identity=before?.id?['id',before.id]:before?.dataset?Object.entries(before.dataset).find(([k])=>['action','category','table','flag','format'].includes(k)):null;document.documentElement.lang=lang;const views={home,connect,capabilities,select,trial,review,running,results,save};document.getElementById('app').innerHTML=`<div class="shell">${topAndRail()}<div class="workspace"><div class="sample-strip">${icon('info')}<span>${t('화면 시안 · 모든 DB와 결과는 예시입니다. 실제 DB에 접속하지 않습니다.','Design preview · All databases and outcomes are samples. No real DB connection.')}</span></div><main id="main" class="content"><div class="page ${state.screen==='results'&&!focus?'settled':''}">${views[state.screen]()}</div></main><footer class="footer">${footer()}</footer></div></div>`;document.querySelector('.step.active')?.scrollIntoView({block:'nearest',inline:'center',behavior:'instant'});if(state.screen==='select')syncTableSelection();if(state.screen==='results'&&focus)animateResult();if(!focus)document.getElementById('main').scrollTop=scrollTop;if(focus){document.getElementById('screen-title')?.focus({preventScroll:true});document.getElementById('main').scrollTop=0;document.getElementById('announcer').textContent=document.getElementById('screen-title')?.textContent||''}else if(identity){const [key,value]=identity;const restored=key==='id'?document.getElementById(value):document.querySelector(`[data-${key}="${CSS.escape(value)}"]`);restored?.focus({preventScroll:true})}}
function go(screen){state.screen=screen;state.error='';if(stages.includes(screen))state.visited.add(screen);render(true)}
function toast(text){clearTimeout(toastTimer);document.getElementById('toast-host').innerHTML=`<div class="toast">${text}</div>`;toastTimer=setTimeout(()=>document.getElementById('toast-host').replaceChildren(),4200)}
function press(button){if(!matchMedia('(prefers-reduced-motion: reduce)').matches)button.animate([{transform:'scale(1)',opacity:1},{transform:'scale(.98)',opacity:.86},{transform:'scale(1)',opacity:1}],{duration:160,easing:'ease-out'})}
function validateConnections(){for(const side of ['source','target']){const d=state[side];if(!d.host.trim()||!d.db.trim()||!d.user.trim())return t('양쪽 서버·DB·조회 계정을 모두 입력하세요.','Fill in the server, database and reader account for both connections.');if(!/^\d+$/.test(d.port)||Number(d.port)<1||Number(d.port)>65535)return t('포트는 1–65535 범위의 정수여야 합니다.','Ports must be integers from 1 to 65535.');if(d.host.startsWith('bad'))return t('예시 서버 주소가 올바르지 않습니다. 주소를 수정해 다시 확인하세요.','The sample server address is invalid. Edit it and try again.')}if(state.source.host===state.target.host&&state.source.port===state.target.port&&state.source.db===state.target.db)return t('같은 DB가 양쪽에 지정됐습니다. 원본과 대상을 확인하세요.','Both sides point to the same sample database. Check the source and target.');return ''}
function updateProgress(){const summary=runSummary();document.getElementById('processed-count').innerHTML=`${summary.done}<small> / ${summary.total} ${t('항목','checks')}</small>`;const meter=document.querySelector('[role=progressbar]');meter.setAttribute('aria-valuenow',summary.done);meter.querySelector('.meter-bar').style.transform=`scaleX(${summary.total?summary.done/summary.total:0})`;const current=state.run.groups.find(g=>g.status==='running');const note=document.getElementById('progress-note');if(note.dataset.group!==(current?.key||'')){note.dataset.group=current?.key||'';note.innerHTML=current?`<span class="running-dot"></span>${catName(current.key)} · ${t('예시 대조 중','Sample comparison')}`:t('다음 분류를 준비하고 있습니다.','Preparing the next category.')}for(const g of state.run.groups){const cell=document.querySelector(`[data-run-state="${g.key}"]`);if(cell.dataset.status!==g.status){cell.dataset.status=g.status;cell.innerHTML=groupState(g);cell.classList.remove('enter');void cell.offsetWidth;cell.classList.add('enter')}document.querySelector(`[data-run-count="${g.key}"]`).textContent=`${g.done} / ${g.total}`}}
function startRun(){state.run=makeRun();go('running');clearInterval(timer);timer=setInterval(()=>{const current=state.run.groups.find(g=>g.status!=='completed');if(!current){clearInterval(timer);state.run.complete=true;const hadCancelFocus=document.activeElement?.dataset.action==='cancel';render();if(hadCancelFocus)document.querySelector('[data-action="show-results"]')?.focus({preventScroll:true});document.getElementById('announcer').textContent=t('예시 검사 완료. 결과 보기 버튼을 사용하세요.','Sample checks finished. Use View results.');return}current.status='running';current.done=Math.min(current.done+1,current.total);if(current.done===current.total)completeGroup(current);updateProgress()},140)}
function openModal(type,payload=''){modal={type,payload,opener:document.activeElement};let title='',body='',actions='';if(type==='research'){title=t('연구 결과 → 검사 → 화면','Research → Checks → Screens');body=`<p class="muted">${t('기본 기능 성공과 데이터 상태·권한·동작의 충족을 구분한 연구 관찰을 다음 방식으로 반영합니다.','The research separates functional success from database-state, permission and behavioral contracts.')}</p><div class="summary-list"><div class="summary-item"><span>RP-D01 · RP-C01/02</span><div>${t('전체 값과 구조·제약 검사 → 분류별 결과','Full values, schema and constraints → Category outcomes')}</div></div><div class="summary-item"><span>RP-A01/02 · RP-O01</span><div>${t('사용자·권한·객체 정의 → 차이와 조회 한계','Users, permissions and object definitions → Differences and visibility limits')}</div></div><div class="summary-item"><span>RP-B01</span><div>${t('별도 시험 DB 동작 → 기대 충족/불충족과 정리 결과','Separate-DB behavior → Expectations and cleanup outcomes')}</div></div><div class="summary-item"><span>RP-S01</span><div>${t('권한 부족·중단·미지원 → 확인 불가/미검증 표시','Permissions, interruption and unsupported checks → Explicit unverified states')}</div></div></div><p class="small" style="margin-top:16px">${t('현재 보이는 것은 예시 화면 연결입니다. 실제 검증 엔진의 탐지 증거는 아직 없습니다.','This is a sample screen mapping. Detection evidence from a real verification engine is not yet available.')}</p>`}else if(type==='permissions'){title=t('조회 범위를 확인하려면','To establish visibility');body=`${notice(t('권한 정의 2개를 확인하지 못했습니다','Two grant checks remain unverified'),t('실제 앱은 숨겨진 객체 목록과 정의를 확인할 권한을 DBMS별로 안내합니다.','The actual app will explain DBMS-specific permissions needed for hidden catalogs and definitions.'),'warn')}<p class="muted" style="margin-top:16px">${t('관리자 전체 권한을 자동 부여하지 않습니다. 필요한 조회 권한을 준비한 뒤 연결·사전 확인부터 전체 재검사합니다.','The app does not grant admin access. Prepare the necessary read permissions and perform a full new check from connection and preflight.')}</p>`}else if(type==='mapping'){title=t('테이블 대응 변경','Change table matching');const name=payload;modal.draft=state.maps[name];body=`<div class="match-source"><small>${t('원본 테이블','Source table')}</small><span class="mono">${esc(name)}</span></div><div class="match-browser"><h3 id="match-target-label">${t('대응할 대상 테이블','Choose a target table')}</h3><div class="search-field">${icon('search')}<label class="sr" for="match-search">${t('대상 테이블 검색','Search target tables')}</label><input id="match-search" type="search" placeholder="${t('대상 테이블 이름 검색','Search target table names')}" autocomplete="off"></div><div class="match-list" id="match-options" role="radiogroup" aria-labelledby="match-target-label">${matchingOptions()}</div><p class="match-query-note" id="match-query-note" aria-live="polite">${t('이미 다른 원본과 연결된 대상은 선택할 수 없습니다.','Targets already matched to another source are unavailable.')}</p></div><p class="small" style="margin-top:16px">${t('일대일 대응만 허용합니다. 이름 차이는 구조 불일치로 남으며 값 변환을 승인하지 않습니다.','Matching must be one-to-one. Name differences remain schema differences; no value transformation is approved.')}</p><div id="modal-error"></div>`;actions=btn('modal-close',t('취소','Cancel'),'quiet')+btn('mapping-apply',t('대응 적용','Apply matching'),'primary','check')}else if(type==='detail'){const g=state.run.groups.find(g=>g.key===payload);title=catName(payload);const def=categoryDefs.find(c=>c.key===payload);body=`<ul class="muted" style="padding-left:20px">${(lang==='ko'?def.detail:def.en).map(x=>`<li>${x}</li>`).join('')}</ul>${g?notice(t('실행 범위','Execution scope'),`${g.done} / ${g.total} ${t('항목 처리','checks processed')} · ${g.status==='completed'?t('완료','Completed'):g.status==='interrupted'?t('중단','Interrupted'):t('미시작','Not started')}`):''}${payload==='trial'?notice(t('예시 정리 상태','Sample cleanup state'),g?.status==='completed'?t('정리 실패 1건 · 앱 자료 T-001 잔여 · 부작용 확인 불가. 실제 자료 변경은 없습니다.','One cleanup failure · Artifact T-001 remains · Side effects unconfirmed. No real data was modified.'):t('시험 미완료. 정리 완료를 확인하지 않았습니다.','Trial incomplete. Cleanup has not been established.'),'warn'):''}<p class="small" style="margin-top:16px">${t('실제 값·행 키·계정명은 표시하지 않습니다.','Row values, keys and principal names are not displayed.')}</p>`}const host=document.getElementById('dialog-host');host.innerHTML=`<dialog ${type==='mapping'?'class="drawer"':''} aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="btn quiet icon-button" type="button" data-action="modal-close" aria-label="${t('닫기','Close')}">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-footer">${actions||btn('modal-close',t('닫기','Close'),'')}</div></dialog>`;const dialog=host.querySelector('dialog');dialog.addEventListener('cancel',e=>{e.preventDefault();closeModal()});dialog.showModal()}
function closeModal(){if(!modal||modal.closing)return;modal.closing=true;const d=document.querySelector('dialog'),opener=modal.opener;const finish=()=>{d?.close();document.getElementById('dialog-host').replaceChildren();modal=null;if(opener?.isConnected)opener.focus({preventScroll:true});else if(opener?.dataset.action)document.querySelector(`[data-action="${CSS.escape(opener.dataset.action)}"]`)?.focus({preventScroll:true})};if(matchMedia('(prefers-reduced-motion: reduce)').matches)finish();else d.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(6px)'}],{duration:160,easing:'ease-out',fill:'forwards'}).finished.then(finish)}
function report(){return {kind:'dmv-ui-sample',version:1,sample:true,run:{id:state.run.id,interrupted:state.run.interrupted,complete:state.run.complete,trialSelected:state.run.trialSelected,groups:state.run.groups.map(g=>({...g})),tables:state.run.tableNames||[],matches:state.run.maps||{}},findings:findings().map(f=>({id:f.id,category:f.key,kind:f.kind,table:f.table,column:f.column,reason:f.reason}))}}
function downloadFile(name,body,mime){const url=URL.createObjectURL(new Blob([body],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function csvCell(v){const s=String(v??'');return '"'+(/^[=+@\-\t\r]/.test(s)?"'":'')+s.replaceAll('"','""')+'"'}
function download(){const r=report();for(const format of state.formats){const filename=`${r.run.id}-sample.${format}`;if(format==='json')downloadFile(filename,JSON.stringify(r,null,2),'application/json');if(format==='csv'){const rows=[['SAMPLE ONLY','run','category','execution','equal','different','unknown'],...r.run.groups.map(g=>['sample',r.run.id,g.key,g.status,g.equal,g.different,g.total-g.equal-g.different]),[],['finding','category','kind','table','column','reason'],...r.findings.map(f=>[f.id,f.category,f.kind,f.table,f.column,f.reason])];downloadFile(filename,'\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}if(format==='html'){downloadFile(filename,`<!doctype html><html lang="${lang}"><meta charset="utf-8"><title>Sample verification report</title><style>body{font:14px/1.6 system-ui;max-width:960px;margin:40px auto;padding:20px;color:#14213d}table{border-collapse:collapse;width:100%}td,th{border:1px solid #dce4f0;padding:12px;text-align:left}</style><h1>${t('예시 검사 보고서','Sample verification report')}</h1><p>${t('화면 시안의 예시입니다. 실제 DB 검사 결과가 아닙니다.','Design preview sample. Not a real DB verification result.')}</p><p>${esc(r.run.id)} · ${r.run.interrupted?t('중단','Interrupted'):t('완료','Completed')}</p><table><tr><th>${t('분류','Category')}</th><th>${t('실행','Execution')}</th><th>${t('일치 / 불일치 / 확인 불가','Equal / different / unknown')}</th></tr>${r.run.groups.map(g=>`<tr><td>${esc(catName(g.key))}</td><td>${esc(g.status)}</td><td>${g.equal} / ${g.different} / ${g.total-g.equal-g.different}</td></tr>`).join('')}</table><h2>${t('차이와 미검증 이유','Differences and gaps')}</h2>${r.findings.map(f=>`<p><strong>${esc(f.id)}</strong> · ${esc(f.table)} · ${esc(f.column)}<br>${esc(f.reason)}</p>`).join('')}</html>`,'text/html;charset=utf-8')}}state.saved=true;render();toast(t('예시 파일 다운로드를 요청했습니다. 브라우저에서 확인하세요.','Sample downloads requested. Check your browser.'))}
async function openFile(file){if(!file)return;try{if(file.size>1024*1024)throw Error();const r=JSON.parse(await file.text());if(r.kind!=='dmv-ui-sample'||r.version!==1||r.sample!==true||!r.run||!Array.isArray(r.run.groups)||r.run.groups.length<1||r.run.groups.length>5)throw Error();const keys=new Set();const validStates=['pending','running','interrupted','completed'];const groups=r.run.groups.map(g=>{if(!categoryDefs.some(c=>c.key===g.key)||keys.has(g.key)||!validStates.includes(g.status))throw Error();keys.add(g.key);for(const k of ['total','done','equal','different','unknown'])if(!Number.isInteger(g[k])||g[k]<0||g[k]>10000)throw Error();if(g.done>g.total||g.equal+g.different+g.unknown>g.done)throw Error();return {key:g.key,total:g.total,done:g.done,status:g.status,equal:g.equal,different:g.different,unknown:g.unknown}});if(typeof r.run.id!=='string'||!/^UI-[A-Z0-9]+$/.test(r.run.id)||typeof r.run.interrupted!=='boolean'||typeof r.run.complete!=='boolean')throw Error();clearInterval(timer);const allowedTables=Object.keys(state.maps);if(!Array.isArray(r.run.tables)||r.run.tables.some(x=>!allowedTables.includes(x))||new Set(r.run.tables).size!==r.run.tables.length)throw Error();const safeMaps={};for(const name of allowedTables){const target=r.run.matches?.[name];if(target&&!allowedTables.includes(target)&&target!=='archive.orders')throw Error();safeMaps[name]=target||name}if(new Set(Object.values(safeMaps)).size!==allowedTables.length)throw Error();state.run={id:r.run.id,groups,interrupted:r.run.interrupted,complete:r.run.complete,trialSelected:keys.has('trial'),tableNames:r.run.tables,maps:safeMaps};state.tables=new Set(r.run.tables);state.maps=safeMaps;state.selected=keys;state.visited=new Set(['results','save']);state.filter='all';go('results');toast(t('저장한 예시 결과를 열었습니다. 재검사는 하지 않았습니다.','Saved sample result opened. No checks were rerun.'))}catch{toast(t('이 시안에서 저장한 정상 예시 JSON이 아닙니다.','This is not a valid sample JSON saved by this preview.'))}document.getElementById('file-open').value=''}
document.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;press(b);const a=b.dataset.action;if(a==='clear-search'){tableQuery='';const field=document.getElementById('table-search');field.value='';updateTableResults();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.getElementById('table-results').animate([{opacity:.5},{opacity:1}],{duration:160,easing:'ease-out'});field.focus();return}if(a==='clear-tables'){filteredTables().forEach(name=>state.tables.delete(name));state.stopped=false;syncTableSelection();updateSelectionFooter();document.getElementById('announcer').textContent=t('검색 결과의 선택을 해제했습니다.','Matching tables were deselected.');return}if(a==='language'){lang=lang==='ko'?'en':'ko';render();if(modal){const old=modal;modal=null;document.getElementById('dialog-host').replaceChildren();openModal(old.type,old.payload)}return}if(a==='modal-close'){closeModal();return}if(a==='mapping-apply'){const collision=Object.entries(state.maps).some(([key,value])=>key!==modal.payload&&value===modal.draft);if(collision){document.getElementById('modal-error').innerHTML=notice(t('대응이 중복됩니다','Matching is duplicated'),t('다른 원본에 이미 대응된 대상은 선택할 수 없습니다.','This target is already matched to another source.'),'error');return}state.maps[modal.payload]=modal.draft;closeModal();render();toast(t('대응을 적용했습니다. 이름 차이는 검사에 남습니다.','Match applied. Name differences remain part of verification.'));return}if(a.startsWith('mapping:')){openModal('mapping',a.slice(8));return}if(a==='research'||a==='permissions'){openModal(a);return}if(a.startsWith('detail:')){openModal('detail',a.slice(7));return}if(a==='open'){document.getElementById('file-open').click();return}if(a==='start'){clearInterval(timer);tableQuery='';state=initial();go('connect');return}if(a==='sample'){state.run=makeRun(true);state.run.groups.forEach(completeGroup);state.run.complete=true;go('results');return}if(a==='restart'){clearInterval(timer);tableQuery='';state.run=null;state.visited=new Set();state.connected=false;state.saved=false;state.stopped=false;state.trial.ready=false;go('connect');return}if(a==='back'){const prev={connect:'home',capabilities:'connect',select:'capabilities',review:'select',save:'results'}[state.screen];if(prev)go(prev);return}if(a.startsWith('stage:')){const next=a.slice(6);if(state.visited.has(next)&&state.screen!=='running')go(next);return}if(a==='advanced'){state.advanced=!state.advanced;render();return}if(a==='connect'){state.error=validateConnections();if(state.error){render();return}state.busy=true;render();await new Promise(r=>setTimeout(r,550));state.busy=false;state.connected=true;render();document.querySelector('[data-action="preflight"]')?.focus({preventScroll:true});document.getElementById('announcer').textContent=t('예시 연결 확인 완료. 조회 범위 확인이 가능합니다.','Sample connections checked. Visibility can now be reviewed.');return}if(a==='preflight'){if(state.connected)go('capabilities');return}if(a==='choose'){go('select');return}if(a.startsWith('expand:')){const key=a.slice(7);state.expanded.has(key)?state.expanded.delete(key):state.expanded.add(key);const open=state.expanded.has(key);b.setAttribute('aria-expanded',String(open));const body=document.getElementById('category-detail-'+key);body.classList.toggle('is-open',open);body.setAttribute('aria-hidden',String(!open));body.inert=!open;document.getElementById('announcer').textContent=catName(key)+' '+t(open?'세부 검사 펼침':'세부 검사 닫힘',open?'details expanded':'details collapsed');return}if(a==='trial'){go('trial');return}if(a==='trial-back'){go('select');return}if(a==='trial-check'){if(!state.trial.validInput.trim()||!state.trial.invalidInput.trim()){state.error=t('시험 값과 기대 결과를 확인하세요.','Confirm trial inputs and expected outcomes.');render();return}if(!state.trial.host.trim()||!state.trial.db.trim()||(state.trial.host===state.source.host&&state.trial.db===state.source.db)||(state.trial.host===state.target.host&&state.trial.db===state.target.db)){state.error=t('다른 예시 시험 DB를 지정하세요. 분리를 확인할 수 없으면 쓰기 시험은 실행할 수 없습니다.','Choose another sample test database. Writes cannot run without established isolation.');render();return}state.trial.ready=true;render();toast(t('예시 시험 준비를 확인했습니다. 실제 DB 검증은 아닙니다.','Sample trial setup confirmed. No actual DB was verified.'));return}if(a==='review'){if(state.selected.size&&(!state.selected.has('trial')||state.trial.ready))go('review');return}if(a==='run'){if(state.stopped)startRun();return}if(a==='cancel'){clearInterval(timer);state.run.interrupted=true;const g=state.run.groups.find(g=>g.status==='running');if(g)g.status='interrupted';render();document.getElementById('announcer').textContent=t('검사가 중단됐습니다. 부분 결과를 확인할 수 있습니다.','Checks interrupted. Partial results are available.');return}if(a==='show-results'){go('results');return}if(a.startsWith('filter:')){state.filter=a.slice(7);render();document.querySelector(`[data-action="${a}"]`)?.focus({preventScroll:true});return}if(a==='save'){go('save');return}if(a==='download'){download();return}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){tableQuery=e.target.value;updateTableResults();return}if(e.target.id==='match-search'){document.getElementById('match-options').innerHTML=matchingOptions(e.target.value);document.getElementById('match-query-note').textContent=t('검색은 대응을 바꾸지 않습니다. 선택 후 적용하세요.','Searching does not change the match. Select a target, then apply.');return}const f=e.target.dataset.field;if(!f||e.target.tagName==='SELECT')return;const [group,key]=f.split('.');if(state[group]&&key){state[group][key]=e.target.value;if(group==='source'||group==='target'){state.trial.ready=false;state.trial.consent=false;state.connected=false;state.visited=new Set(['connect']);document.querySelectorAll('.form-head > .pill').forEach(p=>{p.className='pill';p.textContent=t('미확인','Not checked')});document.querySelector('.notice.ok')?.remove();document.querySelectorAll('.step').forEach(p=>{if(p.dataset.action!=='stage:connect'){p.disabled=true;p.classList.remove('done')}});const forward=document.querySelector('[data-action="preflight"]');if(forward){forward.dataset.action='connect';forward.innerHTML=icon('db')+`<span>${t('두 연결 확인','Check both connections')}</span>`}}if(group==='trial'){state.trial.ready=false;state.trial.consent=false;const consent=document.querySelector('[data-flag="trial.consent"]');if(consent)consent.checked=false;document.querySelector('.notice.ok')?.remove();const confirm=document.querySelector('.footer .btn.primary');if(confirm){confirm.dataset.action='trial-check';confirm.disabled=true;confirm.innerHTML=icon('check')+`<span>${t('시험 준비 확인','Confirm test setup')}</span>`}}}});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.bulk){const names=filteredTables();names.forEach(name=>e.target.checked?state.tables.add(name):state.tables.delete(name));state.stopped=false;syncTableSelection();updateSelectionFooter();document.getElementById('announcer').textContent=t('검색 결과의 선택을 변경했습니다.','Selection updated for matching tables.');return}if(d.field?.startsWith('trial.'))return;if(d.field==='dbms'){state.dbms=e.target.value;const port=state.dbms==='SQL Server'?'1433':state.dbms==='PostgreSQL'?'5432':'3306';state.source.port=state.target.port=port;state.trial.ready=false;state.trial.consent=false;state.connected=false;state.visited=new Set(['connect']);render();return}if(d.modalField&&modal){modal[d.modalField]=e.target.value;document.querySelectorAll('.match-badge').forEach(label=>{if(!label.closest('.unavailable'))label.textContent=label.dataset.targetName===modal.draft?t('선택','Selected'):''});document.getElementById('match-query-note').textContent=t('선택한 대응은 적용 버튼을 눌러 확정합니다.','Press Apply matching to confirm your selection.');return}if(d.category){e.target.checked?state.selected.add(d.category):state.selected.delete(d.category);state.error='';state.stopped=false;updateScopeSelection();return}if(d.table){e.target.checked?state.tables.add(d.table):state.tables.delete(d.table);state.stopped=false;syncTableSelection();updateSelectionFooter();return}if(d.flag){if(d.flag==='stopped')state.stopped=e.target.checked;else if(d.flag==='trial.consent'){state.trial.consent=e.target.checked;if(!e.target.checked)state.trial.ready=false;}render();return}if(d.format){e.target.checked?state.formats.add(d.format):state.formats.delete(d.format);render();return}if(e.target.id==='file-open')openFile(e.target.files[0])});
